use ratatui::{prelude::*, widgets::*}; use crate::{app::App, files::transfer::TransferStatus}; pub fn queue<'a>(app:&App)->Paragraph<'a>{ let mut s=String::new(); for j in &app.transfer_queue.jobs { let dir=match j.direction{crate::files::transfer::TransferDirection::Upload=>"↑",crate::files::transfer::TransferDirection::Download=>"↓"}; let st=match &j.status{TransferStatus::Queued=>"queued".into(),TransferStatus::Active=>format!("{} {}%", app.animator.transfer_dots(), j.progress),TransferStatus::Done=>"done".into(),TransferStatus::Cancelled=>"cancelled".into(),TransferStatus::Failed(e)=>format!("failed: {e}")}; s.push_str(&format!("{dir} {} → {}   {st}
", j.source, j.destination)); } if s.is_empty(){s="No active transfers".into();} Paragraph::new(s).block(Block::bordered().border_style(app.theme.border()).title(" Transfers ")) }